    // ── Consumer visual-styling scan ─────────────────────────────────────

    /// <summary>
    /// The custom button tag names that the scan checks for per-instance
    /// visual-styling attributes.
    /// </summary>
    private static readonly string[] CustomButtonTagNames =
        ["CommonButton", "IconButton", "StageCardButton"];

    /// <summary>
    /// Visual-styling attributes that must not appear on custom button tags
    /// in consumer XAML.  These belong in the theme, defined once per variant
    /// — not tuned per instance.  Layout-only properties
    /// (<c>Grid.Column</c>, <c>DockPanel.Dock</c>, <c>VerticalAlignment</c>,
    /// <c>HorizontalAlignment</c>, <c>Margin</c>, etc.) are not listed here
    /// and remain allowed.
    /// </summary>
    private static readonly string[] ForbiddenVisualAttributes =
        ["Width", "Height", "FontSize", "Padding", "MinHeight", "MinWidth",
         "Background", "BorderBrush", "Foreground"];

    /// <summary>
    /// Returns whether <paramref name="line"/> is the start of a custom
    /// button opening tag (e.g. <c>&lt;buttons:CommonButton …</c>).
    /// </summary>
    private static bool IsCustomButtonTagStart(string line)
    {
        foreach (var name in CustomButtonTagNames)
        {
            // Match <buttons:Name or <buttons:Name (with whitespace or > after)
            if (Regex.IsMatch(line, $@"<buttons:{name}(?:\s|>|$)", RegexOptions.IgnoreCase))
                return true;
        }
        return false;
    }

    /// <summary>
    /// Returns whether <paramref name="line"/> closes an XML opening tag
    /// (contains <c>&gt;</c> not preceded by a dash, or <c>/&gt;</c>).
    /// </summary>
    private static bool LineClosesTag(string line) =>
        Regex.IsMatch(line, @"(?<!-)\>|/\>");

    /// <summary>
    /// Finds every forbidden visual-styling attribute on <paramref name="line"/>
    /// and returns their names.
    /// </summary>
    private static List<string> FindForbiddenAttributes(string line)
    {
        var found = new List<string>();
        foreach (var attr in ForbiddenVisualAttributes)
        {
            if (Regex.IsMatch(line, $@"\b{attr}="))
                found.Add(attr);
        }
        return found;
    }

    /// <summary>
    /// No <c>CommonButton</c>, <c>IconButton</c>, or
    /// <c>StageCardButton</c> tag in consumer .axaml files may carry
    /// per-instance visual-styling attributes
    /// (<c>Width</c>, <c>Height</c>, <c>FontSize</c>, <c>Padding</c>,
    /// <c>MinHeight</c>, <c>MinWidth</c>, <c>Background</c>,
    /// <c>BorderBrush</c>, <c>Foreground</c>).  Those metrics belong in the
    /// theme, defined once per variant.
    /// </summary>
    [Fact]
    public void NoConsumerSetsVisualStylingOnCustomButtons()
    {
        var violations = new List<string>();
        var files = GetAxamlFiles();

        Assert.True(files.Count > 0,
            $"No .axaml files found under {ViewsDir}. "
            + "The Views directory must exist and contain XAML files.");

        foreach (var file in files)
        {
            // Allowed: files inside the central Buttons directory (the
            // ControlTheme markup for the inner Button may use any
            // attribute it needs).
            if (IsInButtonsDirectory(file))
                continue;

            // Allowed: App.axaml (style includes / theme references).
            if (Path.GetFullPath(file) == Path.GetFullPath(AppAxamlPath))
                continue;

            var lines = File.ReadAllLines(file);
            var relativePath = Path.GetRelativePath(RepoRoot, file);
            var insideCustomButton = false;

            for (var i = 0; i < lines.Length; i++)
            {
                var line = lines[i];
                var lineNumber = i + 1;

                if (IsCustomButtonTagStart(line))
                {
                    insideCustomButton = true;

                    // Check the opening line itself for forbidden attrs.
                    var attrs = FindForbiddenAttributes(line);
                    foreach (var attr in attrs)
                        violations.Add($"  {relativePath}:{lineNumber}  →  {attr} on opening tag");
                }

                if (insideCustomButton && !IsCustomButtonTagStart(line))
                {
                    var attrs = FindForbiddenAttributes(line);
                    foreach (var attr in attrs)
                        violations.Add($"  {relativePath}:{lineNumber}  →  {attr}");
                }

                if (insideCustomButton && LineClosesTag(line))
                    insideCustomButton = false;
            }
        }

        Assert.True(violations.Count == 0,
            $"Found {violations.Count} per-instance visual-styling attribute(s) "
            + "on custom button tags in consumer .axaml files.  These metrics "
            + "belong in the theme, defined once per variant — not tuned per "
            + "instance.  Move each value into the appropriate variant's theme "
            + "definition, or delete it if the themed default already serves.\n\n"
            + $"Violations:\n{string.Join("\n", violations)}");
    }

    // ── Central directory existence ──────────────────────────────────────

    /// <summary>
    /// The central Buttons directory must exist as the single home for all
    /// custom button components.
    /// </summary>
    [Fact]
    public void ButtonsDirectory_Exists()
    {
        Assert.True(Directory.Exists(ButtonsDir),
            $"The central Buttons directory must exist at {ButtonsDir}.  "
            + "Create it and place CommonButton, IconButton, StageCardButton, "
            + "and any future custom button components there.");
    }
}

